rule.definition:
a!localVariables(
  local!recipients: if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!recipients),
    null,
    #"SYSTEM_SYSRULES_forEach"(
      items: split(ri!recipients,";"),
      expression: if(
        contains(
          {
            "DPP Operation Editors",
            "HR Director",
            "NBL",
            "Deputy PPL",
            "DPP PIC"
          },
          tostring(fv!item)
        ),
        fv!item,
        clean(stripwith(fv!item," "))
      )
    )
  ),
  local!recipientsGroups: if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!recipients),
    null,
    if(
      and(
        tointeger(ri!statusId)=#"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578617",
        tointeger(property(ri!nomination,"subPositionTypeId",null)) <> #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688"
      ),
      remove(
        local!recipients,
        wherecontains("DPP PIC", local!recipients)
      ),
      local!recipients
    )
  ),
  local!groups: a!flatten(
    #"SYSTEM_SYSRULES_forEach"(
      items: local!recipientsGroups,
      expression: a!groupsByName(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3085024"(fv!item))
    )
  ),
  local!dppGroupMailBox: if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!groups),
    null,
    if(
      contains(
        {
          local!groups
        },
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
      ),
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4718496",
      null
    )
  ),
  local!users: if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!groups),
    null,
    #"SYSTEM_SYSRULES_forEach"(
      items: remove(
        local!groups,
        wherecontains(
          #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922",
          local!groups
        )
      ),
      expression: a!groupMembers(fv!item)
    )
  ),
  local!recipientsCC: a!flatten(
    #"SYSTEM_SYSRULES_forEach"(
      items: local!users,
      expression: property(fv!item,"data",null)
    )
  ),
  local!finalRecipientCC: if(
    or(
      tointeger(ri!statusId) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889",
      tointeger(ri!statusId) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932"
    ),
    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5115647"(
      bu: tostring(property(ri!nomination,"originatingBU",null)),
      statusId: ri!statusId
    ),
    toemailrecipient(
      toemailaddress(
        reject(
          fn!isnull,
          append(
            touniformstring(local!recipientsCC),
            tostring(local!dppGroupMailBox)
          )
        )
      )
    )
  ),
  union(
    local!finalRecipientCC,
    local!finalRecipientCC
  )
)
